import { ArrayMaxSize, IsArray, IsString, MaxLength } from 'class-validator';
import { AGENT_CHAT_MAX_MESSAGES, AGENT_CHAT_MAX_SYSTEM_CHARS, AGENT_CHAT_MAX_TOOLS } from '../agent-chat-limits.js';
import type { IAgentChatToolDefinition, TAgentChatMessage } from '../agent-chat.types.js';

/**
 * `messages`/`tools` are validated only as arrays, not deep-validated field-by-field: they're
 * `@falang/agent`'s own discriminated-union/JSON-Schema shapes, generated by that package and never
 * hand-typed by a user — a malformed request here only breaks the requesting user's own agent run
 * (caught by `AgentSession`'s try/catch), it never reaches another user's data or the compiled build.
 *
 * No `credentialId`/`model` — the model resolves from the app-wide `AgentSettingsService` config
 * instead, see ADR 0031 (private).
 */
export class AgentChatRequestDto {
  @IsString()
  @MaxLength(AGENT_CHAT_MAX_SYSTEM_CHARS)
  system!: string;

  @IsArray()
  @ArrayMaxSize(AGENT_CHAT_MAX_MESSAGES)
  messages!: TAgentChatMessage[];

  @IsArray()
  @ArrayMaxSize(AGENT_CHAT_MAX_TOOLS)
  tools!: IAgentChatToolDefinition[];
}
